# Inject the field before the submit button in AdminSettings
sed -i '/<button/i \
        <div>\n          <label className="block text-xs font-black uppercase tracking-wider text-slate-400 mb-2">Products Page Banner URL</label>\n          <input \n            type="url" \n            value={settings.products_banner_url || '\'''\''}\n            onChange={e => setSettings({...settings, products_banner_url: e.target.value})}\n            className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:border-[#0B1F3A] bg-slate-50 focus:bg-white" \n            placeholder="https://example.com/banner.png"\n          />\n          <p className="text-[10px] text-slate-400 mt-1">Leave empty to use the default text banner.</p>\n        </div>\n' src/components/admin/AdminSettings.tsx
